  AC1  rle_encode returns a list of (count, byte) int tuples, count >= 1
  AC2  rle_decode(rle_encode(x)) == x  (round-trip)
  AC3  decode of valid pairs expands runs to the expected bytes
  AC4  rle_decode raises ValueError for a zero count
  AC5  rle_decode raises ValueError for a negative count
  AC6  rle_decode raises ValueError for a non-int count (float/str/None/complex/bool)
  AC7  rle_decode raises ValueError for a non-int byte (float/str/None/list)
  AC8  rle_decode raises ValueError for a byte outside 0..255
  AC9  rle_decode raises ValueError for malformed pair shapes (not a 2-tuple)
  AC10 rle_decode leaves its input unmutated on error
"""

import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import rle  # noqa: E402


def is_plain_int(value):
    """True for int values, but not bool (bool is a subclass of int)."""
    return isinstance(value, int) and not isinstance(value, bool)


class TestRleEncode(unittest.TestCase):
    def test_encode_returns_list_of_int_tuples(self):
        result = rle.rle_encode(b"aaab")
        self.assertIsInstance(result, list)
        self.assertTrue(all(isinstance(pair, tuple) for pair in result))
        self.assertTrue(all(is_plain_int(c) for c, _ in result))
        self.assertTrue(all(is_plain_int(b) and 0 <= b <= 255 for _, b in result))
        self.assertEqual(result, [(3, 97), (1, 98)])

    def test_encode_counts_are_positive(self):
        result = rle.rle_encode(bytes(range(256)) * 2 + b"zz")
        self.assertTrue(all(c >= 1 for c, _ in result))

    def test_roundtrip_preserves_data(self):
        cases = [b"", b"A", b"AAAAAAAAAAAB", b"\x00\x00\xff\xff", bytes(range(256))]
        for data in cases:
            with self.subTest(data=data[:8]):
                self.assertEqual(rle.rle_decode(rle.rle_encode(data)), data)


class TestRleDecodeValid(unittest.TestCase):
    def test_decode_expands_runs(self):
        self.assertEqual(rle.rle_decode([(2, 65), (1, 66)]), b"AAB")
        self.assertEqual(rle.rle_decode([]), b"")
        self.assertEqual(rle.rle_decode([(2, 0), (1, 255)]), b"\x00\x00\xff")


class TestRleDecodeMalformed(unittest.TestCase):
    def test_zero_count_raises(self):
        with self.assertRaises(ValueError):
            rle.rle_decode([(0, 65)])

    def test_negative_count_raises(self):
        with self.assertRaises(ValueError):
            rle.rle_decode([(-3, 65)])

    def test_non_int_count_raises(self):
        for bad in (1.5, "2", None, 2 + 0j, True, False):
            with self.subTest(count=bad):
                with self.assertRaises(ValueError):
                    rle.rle_decode([(bad, 65)])

    def test_non_int_byte_raises(self):
        for bad in (1.0, "A", None, [65], True):
            with self.subTest(byte=bad):
                with self.assertRaises(ValueError):
                    rle.rle_decode([(1, bad)])

    def test_byte_out_of_range_raises(self):
        for bad in (-1, 256, 1 << 32):
            with self.subTest(byte=bad):
                with self.assertRaises(ValueError):
                    rle.rle_decode([(1, bad)])

    def test_malformed_pair_shape_raises(self):
        for bad_pair in (65, [65], [1, 65, 2]):
            with self.subTest(pair=bad_pair):
                with self.assertRaises(ValueError):
                    rle.rle_decode([bad_pair])

    def test_input_list_not_mutated(self):
        pairs = [(1, 65), (0, 66)]
        with self.assertRaises(ValueError):
            rle.rle_decode(pairs)
        self.assertEqual(pairs, [(1, 65), (0, 66)])


if __name__ == "__main__":
    unittest.main()
