"""Run-length encode/decode for byte strings."""


def rle_encode(data):
    """Encode bytes as a list of (count, byte) pairs, in order."""
    out = []
    for b in data:
        if out and out[-1][1] == b:
            out[-1][0] += 1
        else:
            out.append([1, b])
    return out


def rle_decode(pairs):
    """Decode a list of (count, byte) pairs back to bytes."""
    out = bytearray()
    for count, b in pairs:
        out += bytes([b]) * count
    return bytes(out)
